import Foundation
@testable import ColorComposerCore

/// The `color_matching` solver parity corpus (v1) as committed upstream.
///
/// The corpus is generated by the server's `mix parity.generate` task and
/// carries, for every scenario, the palette response vectors, the target
/// vector, the channel weights, the per-candidate score table, the expected
/// selection, the expected error and explicit tie-break evidence.
struct ParityCorpus: Decodable {
    /// Version of the coupled scorer/selection semantics the corpus captures.
    /// A bump means every expectation moved and the app must follow.
    let algorithmVersion: Int
    /// The server module that produced the expectations.
    let scorer: String
    /// The selection policy the expectations assume.
    let selection: String
    /// The missing-measurement policy the expectations assume.
    let missingPolicy: String
    /// The light sources the server can measure.
    let lightSources: [String]
    /// The scenarios to replay.
    let scenarios: [ParityScenario]
}

/// One replayable scenario: inputs plus the server's expected output.
struct ParityScenario: Decodable {
    let id: String
    let description: String
    /// Weight per light source. May carry sources the app does not know.
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityVector]
    let expected: ParityExpectation
}

/// One measured response vector: a hex color plus its per-light-source
/// brightness. A light source absent from `channels` is *missing*, never zero.
struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

/// The server's expected output for one scenario.
struct ParityExpectation: Decodable {
    /// Score of the selected candidate, or `nil` when nothing was selectable.
    let error: Double?
    /// Per-candidate score table, in palette order.
    let scores: [ParityExpectedScore]
    /// Hex color of the selected candidate, or `nil` when nothing was selectable.
    let selectedHexColor: String?
    /// Index of the selected candidate, or `nil` when nothing was selectable.
    let selectedIndex: Int?
    /// Whether the selection had to break a tie, or `nil` when nothing was selectable.
    let tieBroke: Bool?
    /// Indices sharing the best score.
    let tiedIndices: [Int]
}

/// One entry of the expected score table.
struct ParityExpectedScore: Decodable {
    let index: Int
    let score: ParityScore
}

/// A recorded score: either a number or the `"excluded"` marker the server
/// writes for a candidate that is missing a required measurement.
enum ParityScore: Decodable, Equatable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let marker = try? container.decode(String.self) {
            guard marker == "excluded" else {
                throw DecodingError.dataCorruptedError(
                    in: container,
                    debugDescription: "Unknown score marker \"\(marker)\""
                )
            }
            self = .excluded
            return
        }
        self = .value(try container.decode(Double.self))
    }
}

// MARK: - Mapping onto the solver's domain model

extension ParityVector {
    /// The vector as a solver-ready palette color. Only the light sources the
    /// corpus measured become responses, so an absent channel stays missing
    /// and the scorer excludes the candidate when that channel is weighted.
    func toPaletteColor(id: Int) -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (source, brightness) in channels {
            guard let condition = LightingCondition(rawValue: source) else { continue }
            responses[condition] = IlluminationResponse(brightness: brightness)
        }
        return PaletteColor(
            id: id,
            hex: hexColor,
            rgb: RGBColor(hex: hexColor) ?? RGBColor(red: 0, green: 0, blue: 0),
            responses: responses
        )
    }

    /// The vector as a target response vector; unmeasured channels stay absent.
    func toTargetResponseVector() -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (source, value) in channels {
            guard let condition = LightingCondition(rawValue: source) else { continue }
            brightness[condition] = value
        }
        return TargetResponseVector(brightness)
    }
}

extension ParityScenario {
    /// The scenario weights as solver weights.
    ///
    /// Light sources the app does not know (the corpus carries an
    /// `ultraviolet` case) are ignored, matching the server's
    /// `filter_weights/1`: an unknown source can neither be measured nor
    /// contribute to the error.
    func toChannelWeights() -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double {
            weights[condition.rawValue] ?? 0
        }
        return ChannelWeights(
            white: weight(.white),
            red: weight(.red),
            green: weight(.green),
            blue: weight(.blue),
            lps: weight(.lps)
        )
    }

    /// The scenario palette as solver-ready colors, in corpus order.
    func toPalette() -> [PaletteColor] {
        palette.enumerated().map { $0.element.toPaletteColor(id: $0.offset) }
    }
}
